css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .9); position: relative; }
.loader .can { position: absolute; left: 12%; bottom: 8%; width: 32%; height: 60%; border-radius: 7px; background: linear-gradient(90deg, var(--accent), var(--accent-2) 60%, var(--accent)); animation: spray-shake calc(var(--loader-speed) * .42) ease-in-out infinite; }
.loader .can::before { content: ''; position: absolute; left: 24%; width: 52%; bottom: 100%; height: 20%; border-radius: 3px 3px 0 0; background: #94a3b8; }
.loader i { position: absolute; left: 48%; top: 20%; width: 10%; height: 10%; border-radius: 50%; background: var(--accent); opacity: 0; animation: spray-mist calc(var(--loader-speed) * 1.5) ease-out infinite; }
.loader i:nth-of-type(1) { --dy: -30%; }
.loader i:nth-of-type(2) { --dy: 40%; animation-delay: calc(var(--loader-speed) * .18); }
.loader i:nth-of-type(3) { --dy: 110%; animation-delay: calc(var(--loader-speed) * .36); }
.loader i:nth-of-type(4) { --dy: 175%; animation-delay: calc(var(--loader-speed) * .54); }
@keyframes spray-shake { 0%, 100% { transform: translate(0, 0) rotate(0deg); } 25% { transform: translate(-4%, -3%) rotate(-4deg); } 75% { transform: translate(4%, 3%) rotate(4deg); } }
@keyframes spray-mist { 0% { opacity: 0; transform: translate(0, 0) scale(.35); } 20% { opacity: .85; } 100% { opacity: 0; transform: translate(320%, var(--dy, 0%)) scale(1.6); } }
